import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.util.*;import java.math.*;import java.io.*;import java.nio.charset.StandardCharsets;class ContractTest{static Map<Integer,Integer>frequency(List<Integer>a){Map<Integer,Integer>counts=new HashMap<>();for(int v:a)counts.merge(v,1,Integer::sum);return counts;} @Test void emptyAllNoneAndLinkedList(){for(List<Integer>in:List.of(new ArrayList<Integer>(),new ArrayList<>(List.of(-1,0,1)),new ArrayList<>(List.of(2,3)),new LinkedList<>(List.of(4,0,4,1)))){Map<Integer,Integer>before=frequency(in);int size=in.size();TaskBinding.partition(in,1);assertEquals(size,in.size());assertEquals(before,frequency(in));boolean upper=false;for(int v:in){if(v>1)upper=true;else assertFalse(upper);}}}}
